/* Veyago i18n - nl. Dictionary of English source text -> nl.
   Edit a value to refine wording. Any English string not present here simply
   renders in English (graceful fallback). Loaded on demand by app.js. */
window.__veyagoI18n && window.__veyagoI18n.register("nl",{"strings":{"- Cassian Drefke, Founder & CEO":"- Cassian Drefke, Founder & CEO","- closed beta ahead of Q3 2026 launch.":"- closed beta voorafgaand aan de lancering in Q3 2026.","- cloud, Apple on-device, local, and deterministic fallback, plus ML services for ranking and group consensus.":"- cloud, Apple op je apparaat, lokaal en een deterministische fallback, plus ML-services voor ranking en groepsconsensus.","- Data Not Collected label, one-time purchase model. The studio's first ship, built and in App Store review.":"- Data Not Collected-label, model met eenmalige aankoop. De eerste release van de studio, gebouwd en in App Store-review.","- migrating off React Native to a faster, fully native client.":"- migratie weg van React Native naar een snellere, volledig native client.","- wellbeing layer reads recovery and sleep into the plan, on-device.":"- de wellbeing layer verwerkt herstel en slaap in het plan, op je apparaat.","€350,000 raise":"Investeringsronde van € 350.000","€350K":"€ 350K","289 KB":"289 KB","A clean, branded PDF of any item - perfect for expenses and claims.":"Een strakke, gemerkte PDF van elk item - perfect voor declaraties en claims.","A downloadable kit, ready-to-use descriptions, and a press contact. Writing about travel, consumer AI, or the raise? Start here.":"Een downloadbare kit, kant-en-klare omschrijvingen en een perscontact. Schrijf je over reizen, consumenten-AI of de investeringsronde? Begin hier.","A flywheel rivals can't copy":"Een vliegwiel dat concurrenten niet kunnen kopiëren","A four-round elimination tournament that mirrors how people decide - by comparing, not agonising alone. Up to eighty candidates collapse to one winner, quick and a little addictive. Run it solo, or open a live group session with a \"strong consensus\" signal when you're aligned. The last travel app you'll ever argue over.":"Een afvaltoernooi in vier rondes dat weerspiegelt hoe mensen kiezen - door te vergelijken, niet door er alleen over te piekeren. Tot tachtig kandidaten worden teruggebracht tot één winnaar, snel en een tikje verslavend. Draai het alleen, of open een live groepssessie met een 'sterke consensus'-signaal zodra jullie het eens zijn. De laatste reisapp waar je ooit ruzie over maakt.","A full-stack product studio.":"Een full-stack productstudio.","A layered engine routes between the cloud, Apple Intelligence on your device, and a local model - with a deterministic fallback, so it's never blank, even fully offline.":"Een gelaagde engine schakelt tussen de cloud, Apple Intelligence op je apparaat en een lokaal model - met een deterministische fallback, zodat het nooit leeg blijft, zelfs volledig offline.","A private assistant powered by Apple Intelligence - entirely on-device.":"Een private assistent op basis van Apple Intelligence - volledig op je apparaat.","A quiet layer running under every screen - surfacing a reason here, a summary there, the right nudge at the right moment. You never have to open a chat window and ask.":"Een rustige laag die onder elk scherm meedraait - hier een reden, daar een samenvatting, het juiste duwtje op het juiste moment. Je hoeft nooit een chatvenster te openen om iets te vragen.","A quiet timeline sorted by what's due soonest - surfaced in time to act, not after it's too late.":"Een rustige tijdlijn, gesorteerd op wat het eerst aan de beurt is - op tijd zichtbaar om te handelen, niet als het al te laat is.","A rebuild is priced as whichever package it lands in, with your content and addresses carried across.":"Een herbouw kost hetzelfde als het pakket waarin hij valt, met je content en adressen die meeverhuizen.","A small catalogue, every product held to the same high bar.":"Een kleine catalogus, elk product gehouden aan dezelfde hoge lat.","A small catalogue. A high bar.":"Een kleine catalogus. Een hoge lat.","A small, focused catalogue.":"Een kleine, gerichte catalogus.","A studio, not a factory.":"Een studio, geen fabriek.","A third product is in early development. We'll say more when there's something worth saying.":"Een derde product is in een vroege ontwikkelfase. We vertellen er meer over zodra er iets te vertellen valt.","A world map that fills itself in.":"Een wereldkaart die zichzelf invult.","About":"Over","About the company":"Over het bedrijf","About the studio":"Over de studio","Ad trackers, ever":"Ad trackers, ooit","AI that's honest about what it does":"AI die eerlijk is over wat hij doet","An account is required - we store your email, display name, and travel preferences. Analytics via PostHog: anonymised behaviour, no advertising IDs, no cross-app tracking.":"Een account is verplicht - we bewaren je e-mailadres, weergavenaam en reisvoorkeuren. Analytics via PostHog: geanonimiseerd gedrag, geen advertentie-ID's, geen tracking tussen apps.","An ambient intelligence, not a chatbot.":"Een omgevingsintelligentie, geen chatbot.","An honest progress report, not a highlight reel. June 2026.":"Een eerlijk voortgangsverslag, geen hoogtepuntenreel. Juni 2026.","An independent studio crafting calm, private apps - for where you'll go next, and everything you keep along the way.":"Een onafhankelijke studio die rustige, private apps maakt - voor waar je naartoe gaat, en alles wat je onderweg bewaart.","And the page you are reading, measured the same way.":"En de pagina die je nu leest, op dezelfde manier gemeten.","App Store presence & launch":"App Store-aanwezigheid en lancering","Applied intelligence":"Toegepaste intelligentie","Approach":"Aanpak","Apps":"Apps","Architecture, flows, visual design, and design tokens - with engineering constraints in front of us from the start. No handoff. No redesign after build begins.":"Architectuur, flows, visueel ontwerp en design tokens - met technische randvoorwaarden vanaf het begin in beeld. Geen overdracht. Geen herontwerp nadat de bouw is begonnen.","As of June 2026 the product is roughly 42% complete - mid-rebuild onto a native Flutter client, with health integration underway and first internal betas running. I'd rather show you a working bracket than a deck of promises. The goal is a portfolio of software that earns its place on phones because it's genuinely useful at the moments that matter - not because it captures attention. I incorporated Veyago in New York to build it properly, and I'm raising now to ship version one. If that's the kind of thing you back, write about, or build alongside - I'd like to talk.":"Per juni 2026 is het product ongeveer 42% klaar - midden in de herbouw naar een native Flutter-client, met de health-integratie onderweg en de eerste interne beta's draaiend. Ik laat je liever een werkende bracket zien dan een stapel beloftes. Het doel is een portfolio software die zijn plek op telefoons verdient omdat het echt nuttig is op de momenten die ertoe doen - niet omdat het aandacht vangt. Ik heb Veyago in New York opgericht om het goed te bouwen, en ik haal nu kapitaal op om versie één te lanceren. Als je zoiets steunt, erover schrijft of ernaast bouwt - dan praat ik graag.","Ask Kept":"Ask Kept","Back to home":"Terug naar home","Be the first to explore.":"Wees de eerste die op pad gaat.","Beta":"Beta","Bracket to decide":"Bracket om te beslissen","Build":"Bouwen","Build with Veyago":"Bouw met Veyago","Building together":"Samen bouwen","Built the same way as a Launch page, by the same two people. Measured on 6 September 2026: first load, empty cache, every screenshot at retina resolution.":"Op dezelfde manier gebouwd als een Launch-pagina, door dezelfde twee mensen. Gemeten op 6 september 2026: eerste keer laden, lege cache, elke screenshot op retinaresolutie.","Built to last":"Gebouwd om te blijven","Built to plug into the journey.":"Gebouwd om in de reis te passen.","By app":"Per app","By default, every app":"Standaard, elke app","Cassian founded Veyago in New York in April 2026 with a single brief: build the apps he couldn't find anywhere else. He leads product strategy, design, and company direction - and wrote the brief that became both Kept and the Veyago travel OS. Based in New York.":"Cassian richtte Veyago in april 2026 op in New York met één opdracht: bouw de apps die hij nergens anders kon vinden. Hij leidt productstrategie, design en de richting van het bedrijf - en schreef de opdracht die zowel Kept als de Veyago travel-OS werd. Gevestigd in New York.","Category-aware nudges before a warranty ends or a subscription renews.":"Categoriebewuste duwtjes voordat een garantie afloopt of een abonnement verlengt.","Cloud AI:":"Cloud-AI:","Collect the least, sell none, export or delete anytime.":"Verzamel zo min mogelijk, verkoop niets, exporteer of verwijder wanneer je wilt.","Coming late June 2026":"Komt eind juni 2026","Coming Q3 2026":"Komt in Q3 2026","Coming soon to the":"Binnenkort in de","Common questions":"Veelgestelde vragen","Company":"Bedrijf","Company description":"Bedrijfsomschrijving","Company details.":"Bedrijfsgegevens.","Contact":"Contact","Data minimisation from the architecture up - not compliance retrofitted after the fact. GDPR and App Store privacy label compliance built in. If you're handling health or financial data, this is where we're most useful.":"Dataminimalisatie vanaf de architectuur - geen compliance die achteraf wordt aangeplakt. GDPR- en App Store-privacylabelnaleving standaard ingebouwd. Werk je met gezondheids- of financiële data, dan zijn we hier het nuttigst.","Data sold, ever":"Data verkocht, ooit","Design":"Design","Design, engineering, and everything between.":"Design, engineering en alles daartussen.","Design, engineering, intelligence, and the privacy architecture underneath - all the way to the App Store.":"Design, engineering, intelligentie en de privacyarchitectuur eronder - helemaal tot aan de App Store.","Different apps need different amounts of data. We don't pretend otherwise - we're transparent about where each one sits, and exactly what it reads and why.":"Verschillende apps hebben verschillende hoeveelheden data nodig. We doen niet alsof dat niet zo is - we zijn transparant over waar elke app staat, en precies wat hij leest en waarom.","Different jobs. The same principles.":"Andere taken. Dezelfde principes.","Different products sit at different points on the privacy spectrum - and we're honest about where each one sits. Kept collects nothing and runs on-device. Veyago travel needs more. In every case: we never collect more than the task requires, and we tell you exactly what we read and why before we read it.":"Verschillende producten staan op verschillende punten van het privacyspectrum - en we zijn eerlijk over waar elk product staat. Kept verzamelt niets en draait op je apparaat. Veyago travel heeft meer nodig. In alle gevallen geldt: we verzamelen nooit meer dan de taak vereist, en we vertellen je precies wat we lezen en waarom voordat we het lezen.","Discover":"Ontdekken","Discovery and decision first, then planning and operations, then social and memory. We don't compete feature-by-feature - we make the competition redundant a layer at a time.":"Eerst ontdekken en beslissen, dan plannen en uitvoeren, daarna sociaal en herinneringen. We concurreren niet functie voor functie - we maken de concurrentie laag voor laag overbodig.","Displacement by design":"Verdringing by design","Download press kit":"Download de perskit","Each app does one thing genuinely well and treats your data with respect.":"Elke app doet één ding echt goed en gaat met respect met je data om.","Each product in the Veyago catalogue does one thing genuinely well and treats your data with respect. Different jobs. The same standard.":"Elk product in de Veyago-catalogus doet één ding echt goed en gaat met respect met je data om. Andere taken. Dezelfde maatstaf.","Each product, done properly":"Elk product, goed gedaan","Email support":"E-mailondersteuning","Email us anytime - a real person reads every message.":"Mail ons wanneer je wilt - een echte persoon leest elk bericht.","Every product decision flows from the people who'll live with it. No delegation of vision, no product managers between the idea and the build.":"Elke productbeslissing komt voort uit de mensen die ermee zullen leven. Geen visie die wordt gedelegeerd, geen productmanagers tussen het idee en de bouw.","Every product Veyago ships starts with the same question: is there a version of this that's genuinely excellent, private by default, and worth keeping on your phone for years? If the answer is yes, we build it. If it isn't, we don't.":"Elk product dat Veyago uitbrengt begint met dezelfde vraag: bestaat er een versie hiervan die echt uitstekend is, standaard privé en het waard om jarenlang op je telefoon te houden? Is het antwoord ja, dan bouwen we het. Zo niet, dan niet.","Every suggestion is checked against real place data before it reaches you. Verified facts get a badge - so what you read about a place is real, not invented.":"Elke suggestie wordt gecontroleerd aan echte plaatsgegevens voordat hij je bereikt. Geverifieerde feiten krijgen een badge - zodat wat je over een plek leest echt is, niet verzonnen.","Every swipe, bracket, and veto trains a proprietary preference graph no competitor holds. Hopper built a reported $5B valuation on a booking-data flywheel; ours starts a decision earlier. With enough trips, the co-pilot gets too personal to give up.":"Elke swipe, bracket en veto traint een eigen voorkeursgraaf die geen concurrent heeft. Hopper bouwde een gerapporteerde waardering van $5 miljard op een vliegwiel van boekingsdata; dat van ons begint een beslissing eerder. Met genoeg reizen wordt de co-pilot te persoonlijk om op te geven.","Every trip - and every place you've already photographed - quietly lights up your own world map. Countries explored, routes travelled, continents unlocked. Milestones, streaks, and a growing footprint of everywhere you've been. The quiet reward for all that wandering.":"Elke reis - en elke plek die je al hebt gefotografeerd - laat stilletjes je eigen wereldkaart oplichten. Verkende landen, afgelegde routes, ontgrendelde continenten. Mijlpalen, reeksen en een groeiende voetafdruk van overal waar je bent geweest. De stille beloning voor al dat zwerven.","Everything important, kept safe and on time: warranties, documents, IDs, subscriptions, events, and expiry dates - sorted by what's next and reminded before anything lapses.":"Alles wat belangrijk is, veilig en op tijd bewaard: garanties, documenten, ID's, abonnementen, evenementen en vervaldatums - gesorteerd op wat als volgende komt en herinnerd voordat er iets verloopt.","Everything you keep, organized.":"Alles wat je bewaart, geordend.","Fair monetisation":"Eerlijke verdienmodellen","Fair pricing":"Eerlijke prijzen","Flutter client rebuild underway":"Herbouw van Flutter-client onderweg","Flutter for cross-platform iOS and Android, native Swift for Apple platform exclusives. Both are in production in our own products. We pick the right tool, not the fashionable one.":"Flutter voor cross-platform iOS en Android, native Swift voor Apple-platformexclusieven. Beide draaien in productie in onze eigen producten. We kiezen het juiste gereedschap, niet het modieuze.","Flutter for cross-platform, native Swift where the platform demands it, Supabase for backend, on-device ML where privacy requires it. Built to last.":"Flutter voor cross-platform, native Swift waar het platform daarom vraagt, Supabase voor de backend, on-device ML waar privacy dat vereist. Gebouwd om te blijven.","For clarity":"Voor de duidelijkheid","For journalists.":"Voor journalisten.","Founder & CEO":"Founder & CEO","Founder-led":"Geleid door de oprichter","Founders building something worth building, companies with a product that needs more attention than it's getting. The best projects start with a conversation about the problem. If that's where you are - write to us.":"Oprichters die iets bouwen wat het bouwen waard is, bedrijven met een product dat meer aandacht nodig heeft dan het krijgt. De beste projecten beginnen met een gesprek over het probleem. Als je daar staat - schrijf ons.","Four fast rounds narrow 80 → 20 → 10 → 5 → one. Vote on your own, or open a live session and let your group eliminate down to a single winner together.":"Vier snelle rondes versmallen 80 → 20 → 10 → 5 → één. Stem in je eentje, of open een live sessie en laat je groep samen terugbrengen tot één winnaar.","Four live sites, three of them client businesses that own their code outright. Open any of them and check: not one loads a tracking or analytics script before you agree to it.":"Vier live sites, waarvan drie klantbedrijven die hun code volledig in eigendom hebben. Open er een en controleer het: geen enkele laadt een tracking- of analyticsscript voordat je daarmee instemt.","From $699":"Vanaf € 750","From a hundred maybes to one trip.":"Van honderd misschiens naar één reis.","From sketch to ship.":"Van schets tot release.","Full legal information":"Volledige juridische informatie","Get a calm, well-timed reminder before anything lapses.":"Krijg een rustige, goed getimede herinnering voordat er iets verloopt.","Get in touch":"Neem contact op","Get notified":"Houd me op de hoogte","Grounded, not guessed":"Onderbouwd, niet gegokt","Have a question, a partnership idea, or just want to say hello? We read every message.":"Heb je een vraag, een idee voor een samenwerking, of wil je gewoon hallo zeggen? We lezen elk bericht.","Health and activity data (Apple Health or Health Connect), calendar access for free-window detection, and location are all processed locally. None is stored server-side.":"Gezondheids- en activiteitsgegevens (Apple Health of Health Connect), agendatoegang voor het detecteren van vrije momenten en locatie worden allemaal lokaal verwerkt. Niets wordt op de server opgeslagen.","HealthKit / Health Connect integration in progress":"HealthKit / Health Connect-integratie in uitvoering","Help for each app.":"Hulp voor elke app.","High standards":"Hoge standaarden","Home-screen widgets for what's due, plus a trip-readiness check.":"Beginschermwidgets voor wat aan de beurt is, plus een reisgereedheidscheck.","Honest about what it needs.":"Eerlijk over wat het nodig heeft.","Honest about where each app sits.":"Eerlijk over waar elke app staat.","How can we help?":"Hoe kunnen we helpen?","How do I delete my data?":"Hoe verwijder ik mijn gegevens?","How it works":"Hoe het werkt","How we build":"Hoe we bouwen","How we think":"Hoe we denken","How we think and build":"Hoe we denken en bouwen","How we work":"Hoe we werken","I kept watching the same thing happen. Friends would spend three weeks arguing in a group chat about where to go, give up, and book the city they went to last year. The travel industry starts the moment you already know your destination - Booking, Skyscanner, Airbnb all begin there. The hard part is before that: the discovery, the disagreement, the distance between how you feel and where you'd actually thrive. Nobody had built for it. So I started Veyago.":"Ik zag steeds hetzelfde gebeuren. Vrienden waren drie weken in een groepschat aan het bekvechten over waar ze naartoe zouden gaan, gaven het op en boekten de stad waar ze vorig jaar ook waren. De reisindustrie begint op het moment dat je je bestemming al kent - Booking, Skyscanner en Airbnb beginnen daar allemaal. Het lastige deel zit ervoor: het ontdekken, de onenigheid, de afstand tussen hoe je je voelt en waar je echt zou opbloeien. Niemand had daarvoor gebouwd. Dus begon ik Veyago.","I think I found a bug.":"Ik denk dat ik een bug heb gevonden.","If a design only works because it manipulates someone, we don't ship it.":"Als een ontwerp alleen werkt omdat het iemand manipuleert, brengen we het niet uit.","If the fit is right.":"Als het goed past.","In short":"Kort gezegd","Incorporated April 2026 · Launching Q3 2026":"Opgericht in april 2026 · Lancering in Q3 2026","Independent studio":"Onafhankelijke studio","Insights":"Inzichten","Intelligence does the rest":"Intelligentie doet de rest","Intelligence on-device":"Intelligentie op je apparaat","Intelligence that respects you":"Intelligentie die jou respecteert","Interested in what we're building?":"Geïnteresseerd in wat we bouwen?","Interfaces with taste and restraint. Every screen earns its place.":"Interfaces met smaak en terughoudendheid. Elk scherm verdient zijn plek.","Internal beta running":"Interne beta draait","Internal testing running":"Interne tests draaien","Invest on Wefunder":"Investeer via Wefunder","Investors":"Investeerders","iOS & multiplatform engineering":"iOS- en multiplatform-engineering","Is Kept free?":"Is Kept gratis?","Itinerary generation and Co-pilot responses use GPT-4o, proxied through our own backend. We send anonymised preference context, not your identity. Every permission is requested in context, individually revocable, and one-click account deletion removes everything we hold.":"Het genereren van reisschema's en de antwoorden van de Co-pilot gebruiken GPT-4o, via onze eigen backend. We sturen geanonimiseerde voorkeurscontext mee, niet je identiteit. Elke toestemming wordt in context gevraagd, is afzonderlijk in te trekken, en met één klik je account verwijderen wist alles wat we bewaren.","Join the waitlist":"Schrijf je in op de wachtlijst","Join the waitlist. We'll email you the day Veyago is live - once, to say so, and nothing else.":"Schrijf je in op de wachtlijst. We mailen je op de dag dat Veyago live is - één keer, om dat te zeggen, en verder niets.","Jun 8":"8 jun","Kept · App Store launch":"Kept · App Store-lancering","Kept · Coming late June 2026":"Kept · Komt eind juni 2026","Kept · Data Not Collected":"Kept · Data Not Collected","Kept has no account and talks to no servers of ours. Everything lives on your device and your private iCloud.":"Kept heeft geen account en praat met geen enkele server van ons. Alles staat op je apparaat en in je privé-iCloud.","Kept is a one-time purchase - pay once, own it. No subscription.":"Kept is een eenmalige aankoop - betaal één keer, het is van jou. Geen abonnement.","Kept is a one-time purchase - you pay once, it's yours, no recurring charges. Veyago travel is free with an optional Premium subscription at €4.99/month or €29.99/year. The free tier is genuinely useful, not a crippled demo. No advertising business. No data sales. You pay for the software. You are never the product being sold.":"Kept is een eenmalige aankoop - je betaalt één keer, het is van jou, geen terugkerende kosten. Veyago travel is gratis met een optioneel Premium-abonnement voor € 4,99/maand of € 29,99/jaar. De gratis versie is echt nuttig, geen uitgeklede demo. Geen advertentiebedrijf. Geen dataverkoop. Je betaalt voor de software. Jij bent nooit het product dat verkocht wordt.","Kept launches late June 2026":"Kept lanceert eind juni 2026","Kept launches late June 2026. It keeps everything on your device - there's no account to recover. For help with scanning, reminders, iCloud sync, or your purchase, email us and include your device and iOS version.":"Kept lanceert eind juni 2026. Het bewaart alles op je apparaat - er is geen account om te herstellen. Voor hulp met scannen, herinneringen, iCloud-synchronisatie of je aankoop, mail ons en vermeld je apparaat en iOS-versie.","Kept privacy":"Kept-privacy","Kept Privacy":"Kept-privacy","Kept privacy policy":"Privacybeleid van Kept","Know what it's all worth.":"Weet wat het allemaal waard is.","Learn more":"Meer informatie","Legal":"Juridisch","Legal / Imprint":"Juridisch / Colofon","Library":"Bibliotheek","Listing copy, ASO, screenshots, and a launch plan that doesn't depend entirely on paid acquisition. We've done this for our own products - the same work is available for yours.":"Listingteksten, ASO, screenshots en een lanceringsplan dat niet volledig afhangt van betaalde acquisitie. We hebben dit voor onze eigen producten gedaan - hetzelfde werk is beschikbaar voor dat van jou.","Live in 7 to 10 days":"Live in 7 tot 10 dagen","Local":"Lokaal","Local-first":"Lokaal eerst","Local-first where we can, minimal-data where we can't. Designed so there's little to leak and nothing to sell.":"Lokaal eerst waar het kan, minimale data waar het niet kan. Zo ontworpen dat er weinig te lekken valt en niets te verkopen.","Meet the team":"Maak kennis met het team","Native, fast, and quietly obsessive about craft. We'd rather make two apps we're proud of than ten we're not.":"Native, snel en stilletjes geobsedeerd door vakmanschap. We maken liever twee apps waar we trots op zijn dan tien waar we dat niet op zijn.","Native, fast, reliable. Swift on Apple platforms, built to last.":"Native, snel, betrouwbaar. Swift op Apple-platforms, gebouwd om te blijven.","Never lose track of what matters - warranties, documents, subscriptions, and expiry dates.":"Verlies nooit meer het overzicht over wat ertoe doet - garanties, documenten, abonnementen en vervaldatums.","Never lose track of what matters.":"Verlies nooit meer het overzicht over wat ertoe doet.","No account, no servers of ours, nothing collected. Everything lives on your device and syncs only through your own iCloud. Its App Store privacy label reads \"Data Not Collected\" - the strictest category Apple offers.":"Geen account, geen servers van ons, niets verzameld. Alles staat op je apparaat en synchroniseert alleen via je eigen iCloud. Het App Store-privacylabel vermeldt 'Data Not Collected' - de strengste categorie die Apple biedt.","No account, no servers; your data syncs only through your own iCloud.":"Geen account, geen servers; je data synchroniseert alleen via je eigen iCloud.","No ad trackers, nothing sold, no dark patterns. We collect as little as the job needs - and never the rest.":"Geen ad trackers, niets verkocht, geen dark patterns. We verzamelen zo min als de taak vereist - en nooit de rest.","No dark patterns":"Geen dark patterns","No manufactured urgency. No countdown timers on prices that don't expire. No guilt-trip cancel flows. No burying the unsubscribe. No notifications engineered for our engagement metrics rather than yours. If a design pattern only works because it exploits a cognitive bias or manufactures a feeling you didn't arrive with, we don't ship it.":"Geen kunstmatige urgentie. Geen aftelklokken op prijzen die niet verlopen. Geen schuldopwekkende opzegflows. Geen verstopte afmeldknop. Geen meldingen die zijn ontworpen voor onze betrokkenheidscijfers in plaats van die van jou. Als een ontwerppatroon alleen werkt omdat het een cognitieve bias uitbuit of een gevoel oproept waar je niet mee binnenkwam, brengen we het niet uit.","No monthly fee":"Geen maandelijkse kosten","Nothing leaves your device.":"Niets verlaat je apparaat.","on a Post-Money SAFE (US$4.5M cap), live on Wefunder.":"op een Post-Money SAFE (cap van US$4,5M), live op Wefunder.","On the record":"Officieel vastgelegd","On-device inference for private features; cloud AI (GPT-4o proxied) for generation tasks. We've built the privacy architecture for both and know exactly where the line is.":"On-device inferentie voor privéfuncties; cloud-AI (GPT-4o via proxy) voor generatietaken. We hebben de privacyarchitectuur voor beide gebouwd en weten precies waar de grens ligt.","On-device intelligence":"Intelligentie op je apparaat","On-device intelligence reads the details and files it for you.":"Intelligentie op je apparaat leest de details en archiveert ze voor je.","On-device where it can be. In the cloud, we proxy every call and never send your identity.":"Op je apparaat waar het kan. In de cloud sturen we elke aanroep via een proxy en versturen we nooit je identiteit.","On-device where we can, minimal-data where we can't - honest about where each product sits.":"Op je apparaat waar het kan, minimale data waar het niet kan - eerlijk over waar elk product staat.","On-device wherever possible - health data, preference modelling, and local recommendations stay on your phone. Where cloud AI is genuinely necessary - Veyago travel uses GPT-4o via our own backend for itineraries, briefings, and Co-pilot responses - we proxy every call. We send destination context and anonymised preference signals. We never send your name, health data, or personal details to a third-party AI provider. We will never use an AI model that trains on your personal data without your explicit, informed opt-in.":"Op je apparaat waar mogelijk - gezondheidsgegevens, voorkeursmodellering en lokale aanbevelingen blijven op je telefoon. Waar cloud-AI echt nodig is - Veyago travel gebruikt GPT-4o via onze eigen backend voor reisschema's, briefings en Co-pilot-antwoorden - sturen we elke aanroep via een proxy. We sturen bestemmingscontext en geanonimiseerde voorkeurssignalen mee. We sturen nooit je naam, gezondheidsgegevens of persoonlijke gegevens naar een externe AI-aanbieder. We gebruiken nooit een AI-model dat traint op je persoonlijke gegevens zonder jouw expliciete, weloverwogen opt-in.","One team across the entire engagement - no account manager between you and the builders, no handoff between design and engineering. Small, deliberate, and focused on doing each project properly.":"Eén team gedurende de hele opdracht - geen accountmanager tussen jou en de bouwers, geen overdracht tussen design en engineering. Klein, doelbewust en gericht op het goed doen van elk project.","Opinionated products":"Producten met een mening","Opinionated software. Honest about everything.":"Software met een mening. Eerlijk over alles.","Organize":"Ordenen","Our approach":"Onze aanpak","Our Apps":"Onze apps","Our principles.":"Onze principes.","Our services":"Onze diensten","Partnerships":"Samenwerkingen","Photograph a receipt or document - on-device intelligence fills in the details.":"Fotografeer een bon of document - intelligentie op je apparaat vult de details in.","Plan trips your body can actually take.":"Plan reizen die je lichaam echt aankan.","Polished PDF export":"Verzorgde PDF-export","Post-Money SAFE":"Post-Money SAFE","Powerful. Private. Effortless.":"Krachtig. Privé. Moeiteloos.","Press & investors:":"Pers en investeerders:","Press & media":"Pers en media","Privacy":"Privacy","Privacy & data architecture":"Privacy- en data-architectuur","Privacy architecture":"Privacyarchitectuur","Privacy first":"Privacy eerst","Privacy policy":"Privacybeleid","Privacy Policy":"Privacybeleid","Privacy-first by default":"Standaard privacy eerst","Privacy, across a spectrum":"Privacy, over een spectrum","Private":"Privé","Private by default":"Standaard privé","Private by design":"Privé by design","Product design":"Productdesign","Q3 2026":"Q3 2026","Q3 2026.":"Q3 2026.","Questions, bug reports, feedback, or account help - we read every message and usually reply within a day or two. The fastest way to reach us is email.":"Vragen, bugmeldingen, feedback of hulp met je account - we lezen elk bericht en reageren meestal binnen een dag of twee. De snelste manier om ons te bereiken is e-mail.","Quick answers.":"Snelle antwoorden.","Quick, beautiful, genuinely useful, and respectful of your data. Small catalogue, high standards, no dark patterns.":"Snel, mooi, echt nuttig en respectvol met je data. Kleine catalogus, hoge standaarden, geen dark patterns.","Raising · Post-Money SAFE":"Kapitaalronde · Post-Money SAFE","Raising €350,000":"We halen € 350.000 op","Read each app's formal privacy policy for the full detail - or just take us at our word and try one.":"Lees het formele privacybeleid van elke app voor alle details - of geloof ons gewoon op ons woord en probeer er een.","Read our principles":"Lees onze principes","Read the founder's story":"Lees het verhaal van de oprichter","Read the Kept privacy policy":"Lees het privacybeleid van Kept","Reads the moment":"Leest het moment","Receipts, IDs, manuals, events and renewals - each in its place and easy to find.":"Bonnen, ID's, handleidingen, evenementen en verlengingen - elk op zijn plek en makkelijk te vinden.","Relax":"Ontspan","Reminders that fit":"Herinneringen die passen","Runs anywhere":"Draait overal","Scan":"Scannen","Scan & auto-fill":"Scannen en automatisch invullen","See our apps":"Bekijk onze apps","See services":"Bekijk diensten","See the work":"Bekijk het werk","See what needs you first.":"Zie wat jou het eerst nodig heeft.","See what we've built":"Bekijk wat we hebben gebouwd","Selective on outside work":"Selectief in extern werk","Services":"Diensten","Ship":"Uitbrengen","Six things we don't compromise on.":"Zes dingen waarop we geen concessies doen.","Small by design. We don't scale headcount ahead of quality - we'd rather build two products we're proud of than ten we're not. Outside of the core team, we work with a small number of trusted collaborators on specific projects and capabilities.":"Klein van opzet. We schalen het personeelsbestand niet op vóór de kwaliteit - we bouwen liever twee producten waar we trots op zijn dan tien waar we dat niet op zijn. Buiten het kernteam werken we met een klein aantal vertrouwde medewerkers aan specifieke projecten en capaciteiten.","Small team. High bar.":"Klein team. Hoge lat.","Smart features that respect privacy - on-device wherever possible, responsibly in the cloud where not.":"Slimme functies die privacy respecteren - op je apparaat waar mogelijk, verantwoord in de cloud waar dat niet kan.","Smart features that work for you, not on you - running on your device wherever they can, grounded in real data, never tracking.":"Slimme functies die voor je werken, niet op je - draaiend op je apparaat waar het kan, gegrond in echte data, nooit volgend.","Snap a receipt, warranty, or document - or just type it in.":"Maak een foto van een bon, garantie of document - of typ het gewoon in.","Software for the journey.":"Software voor de reis.","Software with something to say.":"Software met iets te zeggen.","Start a conversation":"Begin een gesprek","Still need a hand?":"Heb je toch hulp nodig?","Stop scrolling. Start eliminating.":"Stop met scrollen. Begin met elimineren.","Store listing, ASO, screenshots, and the pre-submission polish that separates an app that gets featured from one that gets lost.":"Storevermelding, ASO, screenshots en de pre-submissie-afwerking die het verschil maakt tussen een app die wordt uitgelicht en een die verloren gaat.","Strategy, flows, visual design, and design systems built to the same bar we'd hold our own products to. Every screen earns its place.":"Strategie, flows, visueel ontwerp en designsystemen, gebouwd naar dezelfde lat als die we voor onze eigen producten aanhouden. Elk scherm verdient zijn plek.","Support":"Ondersteuning","Swipe to discover":"Swipe om te ontdekken","Swipe, bracket, and let Veyago Intelligence decide - a travel OS that reads how you're feeling and turns it into where to go next.":"Swipe, bracket en laat Veyago Intelligence beslissen - een reis-OS die leest hoe je je voelt en dat omzet in waar je naartoe gaat.","Swipe, bracket, and let Veyago Intelligence decide - the app that turns \"where should we go?\" into a booked trip. Group sessions, AI-generated itineraries, wellbeing layer. Free with Premium. iOS & Android.":"Swipe, bracket en laat Veyago Intelligence beslissen - de app die 'waar zullen we naartoe gaan?' omzet in een geboekte reis. Groepssessies, AI-gegenereerde reisschema's, wellbeing layer. Gratis met Premium. iOS en Android.","Swipe, bracket, and let Veyago Intelligence decide - the travel app that turns \"where should we go?\" into a planned trip, solo or with your whole group.":"Swipe, bracket en laat Veyago Intelligence beslissen - de reisapp die 'waar zullen we naartoe gaan?' omzet in een uitgestippelde reis, alleen of met je hele groep.","Talk to us first":"Praat eerst met ons","Team":"Team","Terms":"Voorwaarden","The \"where should we go?\" spiral ends here. Swipe, bracket down to one winner - solo or live with your group - then let Veyago Intelligence plan the trip and read how it'll sit with your body.":"De spiraal van 'waar zullen we naartoe gaan?' eindigt hier. Swipe, breng het met een bracket terug tot één winnaar - alleen of live met je groep - en laat Veyago Intelligence vervolgens de reis plannen en inschatten hoe die bij je lichaam past.","The Bracket & group sessions":"De Bracket en groepssessies","The catalogue":"De catalogus","The Explorer Map":"De Explorer Map","The founder":"De oprichter","The moment a winner lands, Veyago builds the day-by-day itinerary, finds the flights, watches the fare, and packs the list. Decision to departure, handled.":"Op het moment dat er een winnaar uit de bus komt, bouwt Veyago het dag-voor-dag reisschema, vindt de vluchten, bewaakt de tarieven en maakt de paklijst. Van beslissing tot vertrek, geregeld.","The page you are looking for moved or never existed. Let us get you back on track.":"De pagina die je zoekt is verplaatst of heeft nooit bestaan. We helpen je weer op weg.","The people building it":"De mensen die het bouwen","The people building it.":"De mensen die het bouwen.","The process":"Het proces","The product site for our own travel app, built to the same brief we sell.":"De productsite van onze eigen reisapp, gebouwd volgens dezelfde opdracht die we verkopen.","The same capability that built Kept and Veyago travel - design, engineering, AI integration, privacy architecture - is occasionally available to outside teams. We take on a small number of projects each year. If the fit is right, one team from the first question to the App Store listing.":"Dezelfde capaciteit die Kept en Veyago travel bouwde - design, engineering, AI-integratie, privacyarchitectuur - is af en toe beschikbaar voor externe teams. We nemen elk jaar een klein aantal projecten aan. Als het goed past, één team van de eerste vraag tot de App Store-vermelding.","The same standards. Your product.":"Dezelfde standaarden. Jouw product.","The Studio":"De studio","The studio and our story":"De studio en ons verhaal","The team":"Het team","The travel app · Coming Q3 2026":"De reisapp · Komt in Q3 2026","The value still under warranty, what your subscriptions cost each month, and what's coming due.":"De waarde die nog onder garantie valt, wat je abonnementen per maand kosten en wat er binnenkort verloopt.","The Wellbeing Layer":"De Wellbeing Layer","the whole page, screenshots and all":"de hele pagina, inclusief screenshots","third-party requests":"requests naar derden","This page wandered off.":"Deze pagina is afgedwaald.","Three taps from chaos to calm.":"Drie tikken van chaos naar rust.","Traction":"Tractie","Travel discovery is one of the largest unsolved surfaces in a multi-trillion-dollar industry. Every swipe, bracket, and veto trains a proprietary preference graph no competitor holds - the same kind of flywheel Hopper used to reach a reported $5B valuation, built one layer earlier in the journey. Kept launches late June 2026. A third product is in early development. The raise - €350,000 on a Post-Money SAFE (US$4.5M cap) - funds the Flutter v1 build, closed beta, and Q3 2026 launch.":"Reisontdekking is een van de grootste onopgeloste vlakken in een industrie van vele biljoenen. Elke swipe, bracket en veto traint een eigen voorkeursgraaf die geen concurrent heeft - hetzelfde soort vliegwiel dat Hopper gebruikte om een gerapporteerde waardering van $5 miljard te bereiken, één laag eerder in de reis gebouwd. Kept lanceert eind juni 2026. Een derde product is in een vroege ontwikkelfase. De kapitaalronde - € 350.000 op een Post-Money SAFE (cap van US$4,5M) - financiert de bouw van Flutter v1, de closed beta en de lancering in Q3 2026.","Travel is physical - jet lag, thin sleep, altitude, twelve-hour days. Veyago reads recovery, sleep, and activity from Apple Health or Health Connect: a jet-lag forecast for your exact route, lighter days when your recovery is low, acclimatisation guidance above 2,500 m. Health data never leaves your device.":"Reizen is fysiek - jetlag, korte nachten, hoogte, dagen van twaalf uur. Veyago leest herstel, slaap en activiteit uit Apple Health of Health Connect: een jetlagverwachting voor jouw exacte route, lichtere dagen wanneer je herstel laag is, acclimatisatieadvies boven 2.500 m. Gezondheidsgegevens verlaten nooit je apparaat.","Two apps in flight. More to come.":"Twee apps onderweg. Meer komt eraan.","Two apps shipped or shipping. More to come.":"Twee apps uitgebracht of bijna uit. Meer komt eraan.","Two people building software they couldn't find anywhere else - with a shared belief that apps should earn their place on your phone by being genuinely useful, private by default, and built to last.":"Twee mensen die software bouwen die ze nergens anders konden vinden - met de gedeelde overtuiging dat apps hun plek op je telefoon moeten verdienen door echt nuttig te zijn, standaard privé en gebouwd om te blijven.","Up to 80 destinations, ranked to your taste by Veyago Intelligence - each with a short reason it surfaced for you.":"Tot 80 bestemmingen, naar jouw smaak gerangschikt door Veyago Intelligence - elk met een korte reden waarom hij voor jou naar boven kwam.","Upcoming":"Binnenkort","US$4.5M cap":"Cap van US$4,5M","Veyago Inc · New York C-Corp":"Veyago Inc · New York C-Corp","Veyago Inc. · New York C-Corporation":"Veyago Inc. · New York C-Corporation","Veyago Inc. · New York C-Corporation · EIN 30-1492188 · NYS Entity ID 7899587 · Incorporated April 28, 2026 · Registered in Albany, NY.":"Veyago Inc. · New York C-Corporation · EIN 30-1492188 · NYS Entity ID 7899587 · Opgericht op 28 april 2026 · Geregistreerd in Albany, NY.","Veyago Inc. is a New York C-Corporation building a catalogue of private, intelligent apps for iOS and beyond. Its first app, Kept, launches in late June 2026. Its flagship, Veyago travel, launches Q3 2026. Press contact: hello@veyago.cloud.":"Veyago Inc. is een New York C-Corporation die een catalogus van private, intelligente apps bouwt voor iOS en daarbuiten. De eerste app, Kept, lanceert eind juni 2026. Het vlaggenschip, Veyago travel, lanceert in Q3 2026. Perscontact: hello@veyago.cloud.","Veyago Inc. is a New York C-Corporation. App Store is a trademark of Apple Inc. Apple Intelligence availability varies by device and region.":"Veyago Inc. is een New York C-Corporation. App Store is een handelsmerk van Apple Inc. De beschikbaarheid van Apple Intelligence verschilt per apparaat en regio.","Veyago Inc. was built on a different premise: the apps people carry every day should be genuinely opinionated, private by default, and intelligent without being surveillance. A small catalogue held to a high bar. The flagship solves the part of the journey the whole industry forgot.":"Veyago Inc. is gebouwd op een ander uitgangspunt: de apps die mensen elke dag bij zich dragen, horen echt een mening te hebben, standaard privé te zijn en intelligent zonder surveillance. Een kleine catalogus, gehouden aan een hoge lat. Het vlaggenschip lost het deel van de reis op dat de hele industrie vergat.","Veyago Intelligence in place":"Veyago Intelligence aanwezig","Veyago Intelligence™":"Veyago Intelligence™","Veyago is actively pursuing strategic relationships across airlines, booking platforms, activity providers, and health-data integrators - with early outreach underway to regional carriers and affiliate partners. If you're building in travel, fintech, or wellbeing and see an integration worth exploring, we think in terms of partnerships, not just API keys.":"Veyago werkt actief aan strategische relaties met luchtvaartmaatschappijen, boekingsplatforms, activiteitenaanbieders en integrators van gezondheidsdata - met eerste contacten onderweg naar regionale maatschappijen en affiliate-partners. Bouw je in reizen, fintech of welzijn en zie je een integratie die het verkennen waard is, dan denken we in samenwerkingen, niet alleen in API-sleutels.","Veyago solves the part of the journey every other app ignores: deciding where to go. At its core is the Bracket - a four-round elimination tournament that narrows up to 80 destinations to one winner, alone or with a live group. Veyago Intelligence then generates the itinerary, finds flights, tracks fares, and reads how the trip will sit with your body. Launching Q3 2026. Press: hello@veyago.cloud.":"Veyago lost het deel van de reis op dat elke andere app negeert: beslissen waar je naartoe gaat. De kern is de Bracket - een afvaltoernooi in vier rondes dat tot 80 bestemmingen terugbrengt tot één winnaar, alleen of met een live groep. Veyago Intelligence genereert vervolgens het reisschema, vindt vluchten, volgt tarieven en schat in hoe de reis bij je lichaam past. Lancering in Q3 2026. Pers: hello@veyago.cloud.","Veyago travel · Account required · Minimal by design":"Veyago travel · Account verplicht · Minimaal van opzet","Veyago travel · built · June 2026":"Veyago travel · gebouwd · juni 2026","Veyago travel · Coming Q3 2026":"Veyago travel · Komt in Q3 2026","Veyago travel launch":"Lancering van Veyago travel","Veyago travel launches in Q3 2026. For early access, account help, partnership, or press, get in touch and we'll keep you posted.":"Veyago travel lanceert in Q3 2026. Voor vroege toegang, hulp met je account, een samenwerking of pers, neem contact op en we houden je op de hoogte.","Veyago travel needs more than Kept to do its job - and we'd rather explain that clearly than pretend otherwise.":"Veyago travel heeft meer nodig dan Kept om zijn werk te doen - en dat leggen we liever helder uit dan dat we doen alsof het anders is.","Veyago travel privacy policy":"Privacybeleid van Veyago travel","Vice President":"Vice President","View Kept":"Bekijk Kept","Visit the site ↗":"Bekijk de site ↗","Visit veyago.app":"Ga naar veyago.app","Warranties, documents, subscriptions, and expiry dates - sorted by what's next, reminded before anything lapses. No account. No servers. Data Not Collected label. One-time purchase.":"Garanties, documenten, abonnementen en vervaldatums - gesorteerd op wat als volgende komt, herinnerd voordat er iets verloopt. Geen account. Geen servers. Data Not Collected-label. Eenmalige aankoop.","Warranties, receipts, documents, subscriptions, the food in your fridge and the medicine in your cabinet - Kept keeps anything with a date, and tells you before it slips by. No accounts, no servers, nothing to set up.":"Garanties, bonnen, documenten, abonnementen, het eten in je koelkast en de medicijnen in je kastje - Kept bewaart alles met een datum en zegt het je voordat het je ontglipt. Geen accounts, geen servers, niets om in te stellen.","We build software we'd actually want to use.":"We bouwen software die we zelf echt zouden willen gebruiken.","We build things we couldn't find elsewhere - apps with a point of view that don't compromise it to grow faster. Kept has no account. Veyago has no ad targeting. Neither will change.":"We bouwen dingen die we nergens anders konden vinden - apps met een standpunt die dat niet inleveren om sneller te groeien. Kept heeft geen account. Veyago doet niet aan advertentietargeting. Geen van beide verandert.","We collect the least we need. We never sell it, rent it, or use it to build an advertising profile. Export or delete everything at any time - no dark patterns, no friction, no confirmation screens designed to confuse you.":"We verzamelen het minimum dat we nodig hebben. We verkopen het nooit, verhuren het nooit en gebruiken het nooit om een advertentieprofiel op te bouwen. Exporteer of verwijder alles wanneer je wilt - geen dark patterns, geen frictie, geen bevestigingsschermen die zijn ontworpen om je in de war te brengen.","We don't take on projects designed to harvest user data for advertising, build engagement mechanics that exploit vulnerabilities, or ship dark patterns. We don't sign NDAs that require us to pretend we built something we didn't. And we don't take on more than we can do well - if the fit isn't right, we'll say so at the start.":"We nemen geen projecten aan die zijn opgezet om gebruikersdata te oogsten voor advertenties, betrokkenheidsmechanismen te bouwen die kwetsbaarheden uitbuiten, of dark patterns uit te brengen. We tekenen geen geheimhoudingsverklaringen die ons verplichten te doen alsof we iets hebben gebouwd wat we niet bouwden. En we nemen niet meer aan dan we goed kunnen doen - past het niet goed, dan zeggen we dat meteen.","We have a belief most software companies won't put in writing: ask the least of your users' data, mean every privacy claim you publish, and ship nothing that only works because it manipulates. This page explains exactly how we hold to that - across every product.":"We hebben een overtuiging die de meeste softwarebedrijven niet op papier durven te zetten: vraag zo min mogelijk van de data van je gebruikers, meen elke privacybelofte die je publiceert en breng niets uit dat alleen werkt omdat het manipuleert. Deze pagina legt precies uit hoe we ons daaraan houden - bij elk product.","We keep a small catalogue and hold every product to the same question: would we want this on our own phone for five years? If not, we don't ship it. No features added to look impressive. No rushing to beta. When something leaves this studio it's finished, or it doesn't leave.":"We houden een kleine catalogus aan en toetsen elk product aan dezelfde vraag: zouden we dit vijf jaar lang op onze eigen telefoon willen? Zo niet, dan brengen we het niet uit. Geen functies toegevoegd om indruk te maken. Geen overhaaste beta. Wanneer er iets uit deze studio komt, is het af, of het komt er niet uit.","We occasionally take on a small number of product and engineering projects for outside teams. Same standards, same team.":"We nemen af en toe een klein aantal product- en engineeringprojecten aan voor externe teams. Dezelfde standaarden, hetzelfde team.","We're always open to conversations with people who share our standards - whether you want to back us, write about us, build with us, or build something together.":"We staan altijd open voor gesprekken met mensen die onze standaarden delen - of je ons nu wilt steunen, over ons wilt schrijven, met ons wilt bouwen of samen iets wilt bouwen.","Wessel brings strategic and operational depth to the studio, supporting the company's build-out.":"Wessel brengt strategische en operationele diepgang naar de studio en ondersteunt de opbouw van het bedrijf.","Wessel Gelderblom":"Wessel Gelderblom","What stays on-device:":"Wat op je apparaat blijft:","What unites them":"Wat ze verbindt","What we collect:":"Wat we verzamelen:","What we do":"Wat we doen","What we don't build.":"Wat we niet bouwen.","When does Veyago travel launch?":"Wanneer lanceert Veyago travel?","Where are your privacy policies?":"Waar vind ik jullie privacybeleid?","Where things actually stand.":"Hoe het er werkelijk voor staat.","Who we are":"Wie we zijn","Who you'll work with - the whole team, no account manager.":"Met wie je werkt - het hele team, geen accountmanager.","Why a place is in your deck, what a bracket round revealed, a two-line destination brief, your itinerary's next move - small, evidence-backed touches woven through the app, never in your way.":"Waarom een plek in je deck zit, wat een bracketronde onthulde, een tweeregelige bestemmingsbriefing, de volgende stap in je reisschema - kleine, met bewijs onderbouwde details verweven door de app, nooit in de weg.","Why I'm building Veyago.":"Waarom ik Veyago bouw.","Why Veyago, why now.":"Waarom Veyago, waarom nu.","Widgets & travel":"Widgets en reizen","Work out what the product actually needs to do - not what was specified, but what users genuinely need. We cut scope early and deliberately.":"Uitvogelen wat het product werkelijk moet doen - niet wat er gespecificeerd was, maar wat gebruikers echt nodig hebben. We snijden vroeg en doelbewust in de scope.","You own the code, the repository and the domain":"Jij bezit de code, de repository en het domein","You pay for the software. You are never the product being sold.":"Je betaalt voor de software. Jij bent nooit het product dat verkocht wordt.","Your data is yours":"Je data is van jou","Your data is yours.":"Je data is van jou.","Your data is yours. We mean it.":"Je data is van jou. We menen het.","Your data never leaves your devices.":"Je data verlaat nooit je apparaten.","Your data, your device":"Je data, je apparaat","Your next voyage starts with a swipe.":"Je volgende reis begint met een swipe.","Zero ad trackers":"Nul ad trackers","Zero trackers. No ad networks. Every app starts from \"what's the least we need?\" - and we never sell what we do collect.":"Nul trackers. Geen advertentienetwerken. Elke app begint met 'wat is het minste dat we nodig hebben?' - en we verkopen nooit wat we wél verzamelen.","Launch update":"Update over de lancering","- We'd aimed to launch Kept the week of June 8; it now arrives within two weeks of June 15 as we finish Apple's move to an organization developer account and final certification. We'd rather get it right - updates to follow.":"- We wilden Kept in de week van 8 juni uitbrengen; de app komt nu binnen twee weken na 15 juni, terwijl we Apples overstap naar een organisatie-ontwikkelaarsaccount en de laatste certificering afronden. We doen het liever goed - updates volgen.","Get updates ›":"Updates ontvangen ›","A question, investigated. Findings, no committed build.":"Een vraag, onderzocht. Bevindingen, geen vastgelegde build.","Becomes":"Wordt","Building":"Bouwen","Building in the open":"Open bouwen","Built by a studio. Owned by you.":"Gebouwd door een studio. Van jou.","Built in the open.":"Open gebouwd.","Can a story-driven, narrative path take a true beginner to real coding fluency where reference-style courses lose them?":"Kan een verhalend, narratief pad een echte beginner naar werkelijke programmeervaardigheid brengen waar naslagachtige cursussen hen kwijtraken?","Committed and in active development - also on the Apps page.":"Vastgelegd en in actieve ontwikkeling - ook op de Apps-pagina.","Early development":"Vroege ontwikkeling","Every product starts as a question. We investigate it, prototype an answer, build the ones that hold - and ship them to the Apps page. This is the workbench: the research and the building, in the open.":"Elk product begint als een vraag. We onderzoeken hem, prototypen een antwoord, bouwen de vragen die standhouden - en brengen ze uit naar de Apps-pagina. Dit is de werkbank: het onderzoek en het bouwen, in de open lucht.","Follow along":"Volg mee","Follow the build":"Volg de bouw","Follow the build.":"Volg de bouw.","For most of the cloud era you could build software that was intelligent or private, not both. That trade-off is now narrowing for a specific class of work - latency-sensitive, privacy-critical, structured around your own data - so a privacy-first product can finally offer understanding, not just storage, without sending anything anywhere.":"Het grootste deel van het cloudtijdperk kon je software bouwen die intelligent óf privé was, niet allebei. Die afweging wordt nu kleiner voor een specifieke soort werk - latentiegevoelig, privacykritisch, gestructureerd rond je eigen data - zodat een privacy-first product eindelijk begrip kan bieden, niet alleen opslag, zonder iets ergens naartoe te sturen.","Foundations is built and running - proving the story-driven approach with real learners. The rest of the curriculum is early and phased, with no launch date and no research paper yet. We'd rather prove the idea than rush the rest, which is why it sits here rather than on the Apps page.":"Foundations is gebouwd en draait - en bewijst de verhalende aanpak met echte leerlingen. De rest van het curriculum is vroeg en gefaseerd, zonder lanceerdatum en nog zonder onderzoekspaper. We bewijzen liever het idee dan dat we de rest overhaasten, en daarom zit het hier in plaats van op de Apps-pagina.","Four honest stages. A project only appears once it has something real to show.":"Vier eerlijke fasen. Een project verschijnt pas zodra het iets echts te tonen heeft.","Free · one-time lifetime unlock":"Gratis · eenmalige lifetime-ontgrendeling","Free · optional Premium":"Gratis · optioneel Premium","From a question to a shipped app.":"Van een vraag naar een uitgebrachte app.","Graduated":"Afgestudeerd","Group trips stall not on logistics but on the decision: where do we even go? The working thesis is that a four-round elimination bracket turns paralysis into a decision a group can actually reach together. The full research write-up is in progress.":"Groepsreizen stranden niet op logistiek maar op de beslissing: waar gaan we überhaupt heen? De werkthese is dat een afvalbracket in vier rondes verlamming omzet in een beslissing die een groep daadwerkelijk samen kan bereiken. De volledige onderzoeksuitwerking is in uitvoering.","Held to the same bar":"Aan dezelfde lat gehouden","How a narrative path can teach a beginner to code - being written up.":"Hoe een narratief pad een beginner kan leren programmeren - wordt uitgewerkt.","How intelligence is migrating to the device, and what it means for privacy-first software.":"Hoe intelligentie naar het apparaat verhuist, en wat dat betekent voor privacy-first software.","How intelligence is migrating to the device, WWDC 2026 as its consumer inflection point, and what the narrowing capability-privacy trade-off means for software built to run locally.":"Hoe intelligentie naar het apparaat verhuist, WWDC 2026 als het kantelpunt voor consumenten, en wat de kleiner wordende afweging tussen mogelijkheden en privacy betekent voor software die lokaal draait.","In progress":"In uitvoering","In the pipeline":"In de pipeline","Informs the whole catalogue":"Voedt de hele catalogus","iOS & Android":"iOS en Android","Is the old trade-off between intelligent and private still real - or is it collapsing?":"Bestaat de oude afweging tussen intelligent en privé nog echt - of stort hij in?","Join the Veyago waitlist":"Schrijf je in op de Veyago-wachtlijst","Kept · June 2026 · Working paper":"Kept · juni 2026 · werkdocument","Launching soon":"Binnenkort beschikbaar","Learn about Veyago travel":"Lees meer over Veyago travel","Long-form working papers - the research that justifies each build. More as we publish them.":"Uitgebreide working papers - het onderzoek dat elke bouw rechtvaardigt. Meer zodra we ze publiceren.","Neither is on the App Store yet. We're mid-build and we'd rather show you exactly where each one stands than pretend otherwise. Earlier-stage work lives on":"Geen van beide staat al in de App Store. We zitten midden in de bouw en laten je liever precies zien waar elk product staat dan dat we doen alsof het anders is. Werk in een vroeger stadium vind je op","Newcomer Academy":"Newcomer Academy","No ad targeting":"Geen advertentietargeting","No data sold":"Geen data verkocht","No tracking":"Geen tracking","Nothing here yet - the first graduation will be Kept.":"Hier nog niets - de eerste afstudeerder wordt Kept.","Notify me":"Houd me op de hoogte","On-device":"Op je apparaat","On-device intelligence · June 2026 · Working paper":"Intelligentie op je apparaat · juni 2026 · werkdocument","On-device where it can be":"Op je apparaat waar het kan","Pay once":"Betaal één keer","Platforms":"Platforms","Pricing":"Prijzen","Privacy by design":"Privacy by design","Private, intelligent, beautifully made apps - a small catalogue held to one high bar, and yours to keep rather than software that keeps you.":"Private, intelligente, prachtig gemaakte apps - een kleine catalogus gehouden aan één hoge lat, en van jou om te houden in plaats van software die jou vasthoudt.","Projects":"Projecten","Journal":"Articles","Wallpapers":"Wallpapers","Projects · In-house R&D":"Projects · Eigen R&D","Prototyping":"Prototypen","Read the paper ›":"Lees de paper ›","Research index":"Onderzoeksindex","Researching":"Onderzoeken","Scheduled · late June 2026":"Gepland · eind juni 2026","Scheduled · Q3 2026":"Gepland · Q3 2026","See the apps":"Bekijk de apps","Shipped as an app. The Apps page becomes its home.":"Uitgebracht als app. De Apps-pagina wordt zijn thuis.","Stated once, for the whole catalogue, rather than repeated on each app.":"Eén keer vermeld, voor de hele catalogus, in plaats van herhaald bij elke app.","Story-driven learning":"Verhalend leren","Swipe, bracket, and let Veyago Intelligence decide - a travel OS that turns \"where should we go?\" into a planned trip, solo or with your whole group.":"Swipe, bracket en laat Veyago Intelligence beslissen - een reis-OS die 'waar zullen we naartoe gaan?' omzet in een uitgestippelde reis, alleen of met je hele groep.","Testing an approach in a rough build to see if it holds.":"Een aanpak testen in een ruwe build om te zien of hij standhoudt.","The cognitive burden of life admin, and the case for a private, on-device system of record.":"De cognitieve last van je administratie, en het pleidooi voor een privé systeem van vastlegging op je apparaat.","The cognitive burden of personal life administration, why existing tools fail it, and the case for a private, on-device system of record.":"De cognitieve last van je persoonlijke administratie, waarom bestaande tools daarin tekortschieten, en het pleidooi voor een privé systeem van vastlegging op je apparaat.","The decision problem":"Het beslissingsprobleem","The Edge Moves In":"The Edge Moves In","The failure is not discipline, it is architecture: the records that govern your obligations are scattered with no trusted home, the consequences of losing track arrive late, and nothing watches a deadline before it lapses. The analysis points to a single, private, on-device system of record that does the watching - and prepares the action for you to approve.":"Het falen ligt niet aan discipline maar aan architectuur: de gegevens die je verplichtingen bepalen liggen verspreid zonder vertrouwd thuis, de gevolgen van het overzicht verliezen komen laat, en niets bewaakt een deadline voordat hij verloopt. De analyse wijst naar één privé systeem van vastlegging op je apparaat dat het bewaken doet - en de actie voor je klaarzet om goed te keuren.","The papers behind the products.":"De papers achter de producten.","The pipeline":"De pipeline","The question":"De vraag","The research":"Het onderzoek","The Unkept Life":"The Unkept Life","Two apps, almost here.":"Twee apps, bijna hier.","Warranties, receipts, documents, subscriptions and expiry dates - sorted by what's next and reminded before anything lapses. No account, no servers; everything stays on your device and your iCloud.":"Garanties, bonnen, documenten, abonnementen en vervaldatums - gesorteerd op wat als volgende komt en herinnerd voordat er iets verloopt. Geen account, geen servers; alles blijft op je apparaat en in je iCloud.","We research before we build.":"We onderzoeken voordat we bouwen.","We'd rather show a studio mid-build than a glossy launch that hasn't happened. Follow the build, or be first to know the day each app goes live.":"We laten liever een studio midden in de bouw zien dan een glanzende lancering die nog niet heeft plaatsgevonden. Volg de bouw, of weet als eerste op welke dag elke app live gaat.","We'd rather show the work than a highlight reel. For investors and partners weighing what's next, the research above is the honest version of where we are.":"We laten liever het werk zien dan een hoogtepuntenreel. Voor investeerders en partners die afwegen wat er komt, is het onderzoek hierboven de eerlijke versie van waar we staan.","What every app is held to.":"Waaraan elke app wordt gehouden.","What we found":"Wat we vonden","What we're working on, and why.":"Waar we aan werken, en waarom.","Where it stands":"Hoe het ervoor staat","Why do group trips stall in decision paralysis - and could a swipe-and-eliminate mechanic turn that into a shared decision?":"Waarom stranden groepsreizen in beslisverlamming - en kan een swipe-en-elimineer-mechaniek dat omzetten in een gedeelde beslissing?","Why does so much life admin - warranties, receipts, documents, subscriptions, expiry dates - slip through the cracks?":"Waarom glipt zoveel administratie - garanties, bonnen, documenten, abonnementen, vervaldatums - tussen de mazen door?","Why group trips stall, and the bracket thesis - being written up.":"Waarom groepsreizen stranden, en de bracketthese - wordt uitgewerkt.","Working paper":"Werkdocument","Working paper · June 2026":"Werkdocument · juni 2026","Yours to own":"Van jou om te bezitten","Websites":"Websites","Your business, properly online.":"Jouw bedrijf, goed online.","We build websites for businesses anywhere in the world - landing pages, marketing sites, full corporate sites, and the dashboards and CRMs behind them. Fast, findable, and held to the same bar as our own products.":"We bouwen websites voor bedrijven overal ter wereld - landingspagina's, marketingsites, complete bedrijfswebsites en de dashboards en CRM's erachter. Snel, vindbaar en op hetzelfde niveau als onze eigen producten.","What we build":"Wat we bouwen","From one page to the whole back office.":"Van één pagina tot het hele kantoor erachter.","Landing pages":"Landingspagina's","One page, one job - explain what you do and get the enquiry. Quick to ship, quick to change when the offer changes.":"Eén pagina, één doel - uitleggen wat je doet en de aanvraag binnenhalen. Snel live, snel aangepast als het aanbod verandert.","Marketing & corporate sites":"Marketing- & bedrijfswebsites","Multi-page sites with services, case studies, careers and contact - structured so visitors and search engines both find what they came for.":"Websites met meerdere pagina's voor diensten, cases, vacatures en contact - zo opgebouwd dat bezoekers én zoekmachines vinden waarvoor ze kwamen.","Technical SEO, clean markup, structured data, sensible page speed and content that answers real searches. Findable, not stuffed with keywords.":"Technische SEO, schone markup, gestructureerde data, een fatsoenlijke laadtijd en content die echte zoekvragen beantwoordt. Vindbaar, niet volgepropt met zoekwoorden.","Hand-written HTML, CSS & JS":"Met de hand geschreven HTML, CSS & JS","No builder bloat, no plugin tower that breaks on update. Static sites that load fast, cost almost nothing to host, and still work in five years.":"Geen bouwer-ballast, geen plugintoren die bij de volgende update omvalt. Statische sites die snel laden, bijna niets kosten aan hosting en over vijf jaar nog werken.","React & modern front-ends":"React & moderne front-ends","When a site needs real interaction - configurators, portals, live data - we reach for React. When it doesn't, we don't. The tool follows the job.":"Als een site echte interactie nodig heeft - configurators, portalen, live data - pakken we React. Zo niet, dan niet. Het gereedschap volgt de klus.","Dashboards, CRMs & admin":"Dashboards, CRM's & beheer","The part customers never see: logins, client dashboards, a CRM that fits how you actually sell, invoicing, internal tools. Built on the same stack we run our own business on.":"Het deel dat klanten nooit zien: logins, klantdashboards, een CRM dat past bij hoe je echt verkoopt, facturatie, interne tools. Gebouwd op dezelfde stack waarop ons eigen bedrijf draait.","Already have a site?":"Heb je al een site?","If AI or a builder got you halfway, we'll take it the rest.":"Als AI of een websitebouwer je halverwege bracht, doen wij de rest.","Plenty of businesses already have a website. It came out of Wix, Squarespace, Lovable or a single AI prompt, it looked fine for a week, and now it's slow, impossible to edit, invisible on Google, or simply not the business you actually run. That's the job we take most often.":"Veel bedrijven hebben al een website. Die kwam uit Wix, Squarespace, Lovable of één AI-prompt, zag er een week lang prima uit en is nu traag, niet te bewerken, onvindbaar in Google of gewoon niet het bedrijf dat je echt runt. Dat is de klus die we het vaakst aannemen.","We rebuild it properly: keep what's working, fix the structure underneath, carry your content and your rankings across, and hand you something you own outright rather than rent. If your existing site is genuinely fine, we'll tell you that too.":"We bouwen hem netjes opnieuw: we houden wat werkt, repareren de structuur eronder, nemen je content en je posities mee en geven je iets dat van jou is in plaats van gehuurd. Is je huidige site echt prima? Dan zeggen we dat ook.","Websites start at $699, not $2,000.":"Websites beginnen bij $ 699, niet bij $ 2.000.","The going rate for a business website sits at around $2,000, or €2,250 - out of reach for a lot of the businesses that need one most. Ours start at $699, or €750, excluding tax. You get the full number before we start, not after, and it doesn't move unless the scope does.":"Het gangbare tarief voor een bedrijfswebsite ligt rond de $ 2.000 of € 2.250 - onbereikbaar voor veel bedrijven die er juist een nodig hebben. De onze beginnen bij $ 699 of € 750, exclusief belasting. Je krijgt het volledige bedrag voordat we beginnen, niet erna, en het verandert alleen als de scope verandert.","Why we're cheaper":"Waarom we goedkoper zijn","Because we'd rather have a business that comes back than one invoice that hurt. Fair pricing is how you build a relationship that lasts longer than a single project.":"Omdat we liever een bedrijf hebben dat terugkomt dan één factuur die pijn deed. Een eerlijke prijs is hoe je een relatie bouwt die langer meegaat dan één project.","No agency overhead":"Geen bureaukosten","Small studio, no account managers, no layers between you and the people writing the code. You're not paying for anyone's sales floor.":"Kleine studio, geen accountmanagers, geen lagen tussen jou en de mensen die de code schrijven. Je betaalt niemands verkoopafdeling mee.","No surprises":"Geen verrassingen","One quote, in writing, with what's included and what isn't. No padded hours, no charge for a change of mind on a colour.":"Eén offerte, op papier, met wat erin zit en wat niet. Geen opgeblazen uren, geen rekening omdat je van gedachten verandert over een kleur.","How it goes":"Hoe het gaat","Three steps, no ceremony.":"Drie stappen, zonder poespas.","Talk":"Praten","Tell us what your business does, who you want to reach, and what the current site gets wrong. We come back with a scope and a fixed price - free, and without a sales call in disguise.":"Vertel ons wat je bedrijf doet, wie je wilt bereiken en wat er mis is met de huidige site. Wij komen terug met een scope en een vaste prijs - gratis en zonder verkapt verkoopgesprek.","Design and build together, with something real to look at early. Static HTML or React depending on what the site needs, SEO handled as we go rather than bolted on at the end.":"Ontwerpen en bouwen samen, met al vroeg iets echts om naar te kijken. Statische HTML of React, afhankelijk van wat de site nodig heeft, en SEO doen we onderweg in plaats van er achteraf op te plakken.","Launch":"Live gaan","We ship it, hand over the keys, and show you how to edit it. Want us to keep looking after it? That's an option, never a condition.":"We zetten hem live, geven je de sleutels en laten zien hoe je hem bewerkt. Wil je dat we hem blijven onderhouden? Dat is een optie, nooit een voorwaarde.","Interested?":"Interesse?","Send us a line about your business and where the current site falls short - or that there isn't one yet. We'll tell you honestly what it would take and what it would cost.":"Stuur ons een bericht over je bedrijf en waar de huidige site tekortschiet - of dat er nog geen is. We vertellen je eerlijk wat ervoor nodig is en wat het kost.","Product & app work":"Product- & app-werk","We build websites too.":"We bouwen ook websites.","Landing pages, corporate sites, SEO, and the dashboards and CRMs behind them - for businesses anywhere in the world. Hand-written HTML or React, whichever the job needs.":"Landingspagina's, bedrijfswebsites, SEO en de dashboards en CRM's erachter - voor bedrijven overal ter wereld. Met de hand geschreven HTML of React, wat de klus ook vraagt.","Landing pages to corporate sites":"Van landingspagina tot bedrijfswebsite","SEO built in, not bolted on":"SEO ingebouwd, niet achteraf erop geplakt","Dashboards, CRMs & admin tools":"Dashboards, CRM's & interne tools","Rebuilds of Wix, Lovable & AI-made sites":"Herbouw van Wix-, Lovable- & AI-sites","Fixed price, from $699 or €750":"Vaste prijs, vanaf $ 699 of € 750","Yours to own, not to rent":"Van jou, niet gehuurd","Websites for business":"Websites voor bedrijven","Articles":"Artikelen","Kept · On the App Store":"Kept · In de App Store","Get a quote":"Offerte aanvragen","SEO":"SEO","HTML & CSS":"HTML & CSS","React":"React","Dashboards & CRM":"Dashboards & CRM","From $699 / €750":"Vanaf $699 / €750","Packages":"Pakketten","Three packages. One fixed price each.":"Drie pakketten. Elk met één vaste prijs.","Pick the one that fits, or tell us what you need and we'll say which it is. Every price excludes tax and is confirmed in writing before we start.":"Kies het pakket dat past, of vertel ons wat je nodig hebt en wij zeggen welk het is. Elke prijs is exclusief belasting en wordt schriftelijk bevestigd voordat we beginnen.","One page that explains what you do and gets the enquiry.":"Eén pagina die uitlegt wat je doet en de aanvraag binnenhaalt.","excl. tax":"excl. belasting","or €750":"of € 750","Live in 7 to 10 working days once we have your content":"Live binnen 7 tot 10 werkdagen zodra we je content hebben","One page, up to five sections: hero, what you do, proof or services, about, contact":"Eén pagina, tot vijf secties: hero, wat je doet, referenties of diensten, over ons, contact","A contact form or booking link that actually reaches you":"Een contactformulier of boekingslink die je echt bereikt","Hand-written HTML and CSS, mobile-first and fast":"Met de hand geschreven HTML en CSS, mobile-first en snel","SEO basics done properly: title, description, Open Graph image, structured data, sitemap, Search Console":"SEO-basis goed gedaan: titel, omschrijving, Open Graph-afbeelding, gestructureerde data, sitemap, Search Console","Hosting set up in your own account, domain connected":"Hosting ingericht in je eigen account, domein gekoppeld","One round of revisions":"Eén revisieronde","Start with Launch":"Begin met Launch","Most chosen":"Meest gekozen","Business":"Business","A proper multi-page site for a business people look up before they call.":"Een volwaardige site met meerdere pagina's voor een bedrijf dat mensen opzoeken voordat ze bellen.","or €1,790":"of € 1.790","Typically two to four weeks":"Meestal twee tot vier weken","Up to six pages: services, about, proof, contact and more":"Tot zes pagina's: diensten, over ons, referenties, contact en meer","Everything in Launch, on every page":"Alles uit Launch, op elke pagina","On-page SEO per page, written to answer real searches":"On-page SEO per pagina, geschreven om echte zoekvragen te beantwoorden","Google Business Profile and Search Console set up":"Google Business Profile en Search Console ingericht","Optional news or blog section you can update yourself":"Optioneel een nieuws- of blogsectie die je zelf kunt bijwerken","Two rounds of revisions":"Twee revisierondes","Start with Business":"Begin met Business","Back office":"Back office","The site plus the tools behind it: logins, dashboards, a CRM, invoicing.":"De site plus de tools erachter: logins, dashboards, een CRM, facturatie.","from":"vanaf","or from €4,100":"of vanaf € 4.100","Typically four to eight weeks, scoped per project":"Meestal vier tot acht weken, scope per project bepaald","Everything in Business":"Alles uit Business","A login area: client dashboard, CRM, invoicing or an internal tool":"Een inlogomgeving: klantdashboard, CRM, facturatie of een interne tool","Built on Supabase, the same stack we run our own business on":"Gebouwd op Supabase, dezelfde stack waarop ons eigen bedrijf draait","Scoped and quoted in writing before we start":"Scope en offerte op papier voordat we beginnen","Handover with documentation and a walkthrough":"Overdracht met documentatie en een rondleiding","Talk about Back office":"Praat met ons over Back office","Rebuilding an existing Wix, Squarespace, Lovable or AI-built site is priced as whichever package it lands in, with your content and addresses carried across. Nothing is rented: you own the code, the repository and the domain, and you can leave at any time.":"Het opnieuw bouwen van een bestaande site uit Wix, Squarespace, Lovable of een AI-tool kost hetzelfde als het pakket waarin hij valt, met je content en adressen meegenomen. Niets wordt gehuurd: de code, de repository en het domein zijn van jou, en je kunt op elk moment weg.","What costs extra":"Wat extra kost","Copywriting":"Copywriting","We write the page from your notes":"Wij schrijven de pagina op basis van je aantekeningen","from $120 / €130 per page":"vanaf $120 / €130 per pagina","Extra pages":"Extra pagina's","Beyond what the package includes":"Bovenop wat het pakket bevat","$140 / €150 each":"$140 / €150 per stuk","Care plan":"Onderhoudsplan","Updates, uptime monitoring, backups, small changes":"Updates, uptime-monitoring, back-ups, kleine wijzigingen","$49 / €49 per month":"$49 / €49 per maand","Rush delivery":"Spoedlevering","When the date is not negotiable":"Als de datum niet onderhandelbaar is","Logo and brand design":"Logo en huisstijl","Not something we do, but we know people who do it well":"Doen we zelf niet, maar we kennen mensen die het goed doen","Referred out":"Doorverwijzing","Questions":"Vragen","What people ask before they write.":"Wat mensen vragen voordat ze schrijven.","How long does it take?":"Hoe lang duurt het?","A Launch page is usually live 7 to 10 working days after we have your content. A Business site takes two to four weeks, a Back office project four to eight. The clock starts when the text, photos and logo are in, so the fastest thing you can do is gather those first.":"Een Launch-pagina staat meestal 7 tot 10 werkdagen nadat we je content hebben live. Een Business-site duurt twee tot vier weken, een Back office-project vier tot acht. De klok begint te lopen zodra tekst, foto's en logo binnen zijn, dus het snelste wat je kunt doen is die eerst verzamelen.","What do I need to give you?":"Wat moet ik aanleveren?","Your logo, whatever text you have (rough notes are fine), photos if you have good ones, and access to your domain. If you would rather we write the pages from your notes, that is the copywriting extra. We handle everything else, including the hosting account and the search set-up.":"Je logo, de tekst die je hebt (ruwe aantekeningen zijn prima), foto's als je goede hebt, en toegang tot je domein. Wil je liever dat wij de pagina's op basis van je aantekeningen schrijven, dan is dat de extra optie copywriting. De rest regelen wij, inclusief het hostingaccount en de zoekmachine-instellingen.","Do I own the website?":"Is de website van mij?","Yes, all of it. The code lives in a repository in your name, the hosting runs in your own account and the domain stays yours. There is no monthly fee unless you choose the care plan, and you can hand the site to anyone else at any time. We build it so that you never need us again, then hope you come back anyway.":"Ja, helemaal. De code staat in een repository op jouw naam, de hosting draait in je eigen account en het domein blijft van jou. Er zijn geen maandelijkse kosten tenzij je voor het onderhoudsplan kiest, en je kunt de site op elk moment aan iemand anders overdragen. We bouwen hem zo dat je ons nooit meer nodig hebt, en hopen dat je toch terugkomt.","What does hosting cost?":"Wat kost hosting?","For most small business sites, nothing. A hand-written static site fits comfortably in the free tier at Vercel or Cloudflare, and we set it up in your own account rather than ours. The domain is the only recurring cost, typically $10 to $20 a year from your registrar.":"Voor de meeste sites van kleine bedrijven: niets. Een met de hand geschreven statische site past ruim binnen het gratis abonnement van Vercel of Cloudflare, en we richten het in je eigen account in, niet in het onze. Het domein is de enige terugkerende kostenpost, meestal $10 tot $20 per jaar bij je registrar.","Can I edit the site myself?":"Kan ik de site zelf bewerken?","Yes. Text and images are plain files, and at launch we walk you through changing them. If you expect frequent updates, a news section you can edit is included in Business, and the care plan covers small changes for you.":"Ja. Tekst en afbeeldingen zijn gewone bestanden, en bij de livegang laten we je zien hoe je ze aanpast. Verwacht je regelmatig updates, dan zit een nieuwssectie die je zelf kunt bewerken in Business, en het onderhoudsplan dekt kleine wijzigingen voor je.","I already have a site. Will I lose my Google rankings?":"Ik heb al een site. Verlies ik mijn posities in Google?","Not if the move is done properly, which is most of what a rebuild is. We carry your content across, keep the addresses that already rank, redirect any that change, and register the new site in Search Console before it goes live. If your current site is genuinely fine we will tell you that too, free.":"Niet als de overstap goed wordt gedaan, en dat is het grootste deel van wat een herbouw is. We nemen je content mee, behouden de adressen die al scoren, sturen adressen die veranderen door en registreren de nieuwe site in Search Console voordat hij live gaat. Is je huidige site echt prima, dan zeggen we dat ook, gratis.","What does “excluding tax” mean for me?":"Wat betekent “exclusief belasting” voor mij?","Prices are shown before sales tax or VAT. The tax that applies to you, if any, is added to the quote and shown before you commit, so the number you accept is the number you pay. Business customers in the EU with a VAT number are invoiced under the reverse-charge rule.":"Prijzen zijn exclusief sales tax of btw. De belasting die op jou van toepassing is, als die er is, wordt aan de offerte toegevoegd en getoond voordat je akkoord gaat, zodat het bedrag dat je accepteert het bedrag is dat je betaalt. Zakelijke klanten in de EU met een btw-nummer worden gefactureerd met btw verlegd.","How do payments work?":"Hoe werkt de betaling?","Half to schedule the work, half at launch, by card or bank transfer against an invoice from Veyago Inc. For Back office projects we agree milestones instead. Nothing is charged before you have accepted a written quote.":"De helft om het werk in te plannen, de helft bij de livegang, per kaart of bankoverschrijving op een factuur van Veyago Inc. Voor Back office-projecten spreken we in plaats daarvan mijlpalen af. Er wordt niets in rekening gebracht voordat je een schriftelijke offerte hebt geaccepteerd.","What if I want changes after launch?":"Wat als ik na de livegang iets wil veranderen?","Every package includes revision rounds while we build. After launch, small changes are part of the care plan, and anything larger is quoted as an extra page or a fixed piece of work before we do it. You will never get an hourly bill you did not expect.":"Elk pakket bevat revisierondes tijdens het bouwen. Na de livegang vallen kleine wijzigingen onder het onderhoudsplan, en alles wat groter is wordt vooraf geoffreerd als extra pagina of als afgebakend stuk werk. Je krijgt nooit een urenfactuur die je niet zag aankomen.","Will my site use cookies or trackers?":"Gebruikt mijn site cookies of trackers?","Not unless you ask for them. We do not add ad trackers, third-party analytics or a cookie banner by default, which is also why the sites are fast. If you need visitor numbers, we can add privacy-respecting analytics that keep your visitors’ data on your own domain.":"Niet tenzij je erom vraagt. We voegen standaard geen advertentietrackers, externe analytics of cookiebanner toe, en dat is ook waarom de sites snel zijn. Heb je bezoekersaantallen nodig, dan kunnen we privacyvriendelijke analytics toevoegen die de gegevens van je bezoekers op je eigen domein houden.","Tell us about your business.":"Vertel ons over je bedrijf.","A few lines are enough. Within one working day you get either a couple of questions or a scope and a fixed price in writing. No sales call unless you want one.":"Een paar regels zijn genoeg. Binnen één werkdag krijg je óf een paar vragen, óf een scope en een vaste prijs op papier. Geen verkoopgesprek, tenzij je dat zelf wilt.","Your name":"Je naam","Email":"E-mail","(optional)":"(optioneel)","Current website":"Huidige website","(if there is one)":"(als die er is)","What should the site do for you?":"Wat moet de site voor je doen?","What you sell, who you want to reach, and what the current site gets wrong. Rough is fine.":"Wat je verkoopt, wie je wilt bereiken en wat er mis is met de huidige site. Het hoeft niet netjes te zijn.","Send":"Versturen","Goes straight to us through our own server. No form provider, no tracking, and we never share it.":"Gaat rechtstreeks naar ons via onze eigen server. Geen formulierdienst, geen tracking, en we delen het nooit.","Thanks. It's on its way.":"Bedankt. Het is onderweg.","You'll hear back within one working day, from a person. If it's urgent in the meantime, write to hello@veyago.cloud.":"Je hoort binnen één werkdag van ons, van een echt persoon. Is het intussen dringend, mail dan naar hello@veyago.cloud.","Sending…":"Versturen…","Please check the highlighted fields.":"Controleer de gemarkeerde velden.","That didn't go through.":"Dat is niet gelukt.","Too many messages from this address just now.":"Te veel berichten van dit adres op dit moment.","Send it by email instead":"Stuur het liever per e-mail","Veyago travel":"Veyago travel","Kept":"Kept","hello@veyago.cloud":"hello@veyago.cloud","Instagram ↗":"Instagram ↗","veyago.app ↗":"veyago.app ↗","Invest on Wefunder ↗":"Investeer via Wefunder ↗","Where can we see it?":"Waar kunnen we het zien?","What are you building, and where is it stuck?":"Wat bouw je, en waar loopt het vast?","The problem, the stage you're at, and what you'd want from us. Rough is fine.":"Het probleem, de fase waarin je zit en wat je van ons zou willen. Het hoeft niet netjes te zijn.","Company name":"Bedrijfsnaam","Veyago":"Veyago","Skip to content":"Ga naar de inhoud","Your business":"Je bedrijf","Leave this field empty":"Laat dit veld leeg","Websites for small businesses anywhere in the world - landing pages, marketing sites, full company sites, and the dashboards and CRMs behind them. Fast, findable, and held to the same bar as our own products.":"Websites voor kleine bedrijven, overal ter wereld - landingspagina's, marketingsites, complete bedrijfswebsites en de dashboards en CRM's erachter. Snel, vindbaar en op hetzelfde niveau als onze eigen producten.","Get a fixed quote":"Vraag een vaste prijs aan","See the packages":"Bekijk de pakketten","Fixed prices from $699 · a written quote within one working day · you own everything we build":"Vaste prijzen vanaf € 750 · een schriftelijke offerte binnen één werkdag · alles wat we bouwen is van jou","This site is the sample. It is built the same way as the Launch package, by the same two people, and the numbers are the page you are reading.":"Deze site is het voorbeeld. Hij is op dezelfde manier gebouwd als het Launch-pakket, door dezelfde twee mensen, en de cijfers gaan over de pagina die je nu leest.","188 KB":"188 KB","the whole page, uncompressed":"de hele pagina, ongecomprimeerd","requests to load it":"requests om hem te laden","third-party requests, no trackers":"requests naar derden, geen trackers","a month to host":"per maand aan hosting","View the source ↗":"Bekijk de broncode ↗","Recent work":"Recent werk","Sites we built and look after.":"Sites die we hebben gebouwd en onderhouden.","Four live sites. Every one of them loads without a single tracking or analytics script - open one and check.":"Vier live sites. Geen van alle laadt ook maar één tracking- of analyticsscript - open er een en controleer het.","Tanja Drefke Consult ↗":"Tanja Drefke Consult ↗","TDC Digital Advisory ↗":"TDC Digital Advisory ↗","Veyago travel ↗":"Veyago travel ↗","IE Global ↗":"IE Global ↗","td-consult.info":"td-consult.info","tdc-advisory.com":"tdc-advisory.com","veyago.app":"veyago.app","ie-global.net":"ie-global.net","Enterprise transformation and strategy consultancy.":"Adviesbureau voor enterprise-transformatie en strategie.","tracking scripts":"trackingscripts","Senior-led enterprise advisory: AI governance and digital transformation.":"Senior enterprise-advies: AI-governance en digitale transformatie.","The product site for our own travel app.":"De productsite van onze eigen reisapp.","Digital systems, websites and platforms built for growth.":"Digitale systemen, websites en platforms gebouwd voor groei.","Measured on 5 September 2026, first load, empty cache: none of the four loads a tracking or analytics script. The clients own their sites outright, which is the point.":"Gemeten op 5 september 2026, eerste keer laden, lege cache: geen van de vier laadt een tracking- of analyticsscript. De klanten zijn volledig eigenaar van hun site, en dat is precies de bedoeling.","If Wix, Squarespace or an AI builder got you halfway, we'll take it the rest.":"Als Wix, Squarespace of een AI-builder je halverwege bracht, brengen wij je de rest.","Plenty of businesses already have a website. It came out of Wix, Squarespace, Lovable or a single AI prompt, it looked fine for a week, and now it's slow, impossible to edit, invisible on Google, or simply not the business you actually run. That's the job we're asked about most.":"Veel bedrijven hebben al een website. Hij kwam uit Wix, Squarespace, Lovable of één AI-prompt, zag er een week goed uit, en is nu traag, niet te bewerken, onzichtbaar op Google, of gewoon niet het bedrijf dat je echt runt. Dat is de klus waar we het vaakst over benaderd worden.","A fixed price in writing before any payment":"Een vaste prijs op papier vóór enige betaling","Half to schedule, half at launch, nothing before you accept":"De helft om in te plannen, de helft bij oplevering, niets voordat je akkoord gaat","A reply from a person within one working day":"Een antwoord van een mens binnen één werkdag","If your current site is genuinely fine, we say so, free":"Als je huidige site echt goed is, zeggen we dat, gratis","Right for most businesses":"Past bij de meeste bedrijven","Who you'll work with":"Met wie je werkt","Two people, no account manager.":"Twee mensen, geen accountmanager.","Cassian Drefke":"Cassian Drefke","WG":"WG","Native":"Native","iOS":"iOS","Founder. Writes the quote, designs and builds the site, and answers your email within one working day.":"Oprichter. Schrijft de offerte, ontwerpt en bouwt de site, en beantwoordt je e-mail binnen één werkdag.","Strategy and operations. Keeps the project on its dates and the handover complete.":"Strategie en operatie. Houdt het project op schema en zorgt voor een complete overdracht.","Which package are you looking at?":"Naar welk pakket kijk je?","Not sure yet":"Weet ik nog niet","or write to":"of schrijf naar","Please tell us your name.":"Vertel ons je naam.","Enter a valid email address.":"Vul een geldig e-mailadres in.","That website address does not look right.":"Dat websiteadres ziet er niet goed uit.","+1 (518) 913 2531 (US)":"+1 (518) 913 2531 (VS)","+1 (943) 273 6579 (international)":"+1 (943) 273 6579 (internationaal)","Private apps and proper websites · New York":"Private apps en degelijke websites · New York","Language":"Taal","The Tanja Drefke Consult homepage":"De homepage van Tanja Drefke Consult","The TDC Digital Advisory homepage":"De homepage van TDC Digital Advisory","The Veyago travel product site":"De productsite van Veyago travel","The IE Global homepage":"De homepage van IE Global","Our side of the deal":"Onze kant van de afspraak","Looking for a website for your business? That is a separate, fixed-price service from $699.":"Zoek je een website voor je bedrijf? Dat is een aparte dienst met vaste prijs, vanaf € 750.","A website that brings in customers.":"Een website die klanten oplevert.","Fixed price from $699, live in about ten working days. Hand-written so it opens fast on a phone, findable on Google, and yours to own with no monthly fee.":"Vaste prijs vanaf € 750, live in ongeveer tien werkdagen. Met de hand geschreven zodat hij snel opent op een telefoon, vindbaar op Google, en van jou zonder maandelijkse kosten.","Found on Google for what you sell":"Gevonden op Google voor wat je verkoopt","Opens in under a second on a phone":"Opent in minder dan een seconde op een telefoon","One written price before any work":"Eén schriftelijke prijs vóór enig werk","Rebuilds of Wix, Squarespace & AI-made sites":"Herbouw van Wix-, Squarespace- en AI-sites","Dashboards & CRMs when you need them":"Dashboards & CRM's als je ze nodig hebt","Yours to own, no monthly fee":"Van jou, zonder maandelijkse kosten","On the App Store":"In de App Store","An honest progress report, not a highlight reel.":"Een eerlijk voortgangsverslag, geen hoogtepuntenshow.","Veyago travel · Flutter rebuild":"Veyago travel · Flutter-herbouw","Kept is on the App Store":"Kept staat in de App Store","- Data Not Collected label, one-time purchase model. The studio's first ship.":"- Data Not Collected-label, model met eenmalige aankoop. De eerste release van de studio.","The Kept app showing upcoming items sorted by what's next":"De Kept-app met aankomende items gesorteerd op wat eerst komt","One on the App Store, one on the way.":"Eén in de App Store, één onderweg.","The product is mid-rebuild onto a native Flutter client, with health integration underway and internal betas running. I'd rather show you a working bracket than a deck of promises. The goal is a portfolio of software that earns its place on phones because it's genuinely useful at the moments that matter - not because it captures attention. I incorporated Veyago in New York to build it properly, and I'm raising now to ship version one. If that's the kind of thing you back, write about, or build alongside - I'd like to talk.":"Het product wordt momenteel herbouwd op een native Flutter-client, met de gezondheidsintegratie in aanbouw en interne bèta's die draaien. Ik laat je liever een werkende bracket zien dan een deck vol beloftes. Het doel is een portfolio van software die zijn plek op je telefoon verdient omdat hij echt nuttig is op de momenten die ertoe doen - niet omdat hij je aandacht vangt. Ik heb Veyago in New York opgericht om het goed te bouwen, en ik haal nu geld op om versie één uit te brengen. Als dat het soort ding is dat je steunt, waarover je schrijft of waaraan je meebouwt - dan praat ik graag verder.","Kept has shipped. Veyago travel is mid-build, and we'd rather show you exactly where it stands than pretend otherwise. Earlier-stage work lives on":"Kept is uit. Veyago travel is in aanbouw, en we laten je liever precies zien waar het staat dan te doen alsof. Werk in een eerder stadium staat op","Four live sites. None of them loads a tracking or analytics script before you agree to one - open one and check.":"Vier live sites. Geen van alle laadt een tracking- of analyticsscript voordat je daarmee instemt - open er een en controleer het.","Measured on 5 September 2026, first load, empty cache, nothing accepted: none of the four loads a tracking or analytics script. The clients own their sites outright, which is the point.":"Gemeten op 5 september 2026, eerste keer laden, lege cache, niets geaccepteerd: geen van de vier laadt een tracking- of analyticsscript. De klanten zijn volledig eigenaar van hun site, en dat is precies de bedoeling.","trackers on load":"trackers bij het laden","Kept is on the App Store. It keeps everything on your device - there's no account to recover. For help with scanning, reminders, iCloud sync, or your purchase, email us and include your device and iOS version.":"Kept staat in de App Store. Het bewaart alles op je apparaat - er is geen account om te herstellen. Voor hulp met scannen, herinneringen, iCloud-synchronisatie of je aankoop, mail ons en vermeld je apparaat en iOS-versie.","Travel discovery is one of the largest unsolved surfaces in a multi-trillion-dollar industry. Every swipe, bracket, and veto trains a proprietary preference graph no competitor holds - the same kind of flywheel Hopper used to reach a reported $5B valuation, built one layer earlier in the journey. Kept is on the App Store. A third product is in early development. The raise - €350,000 on a Post-Money SAFE (US$4.5M cap) - funds the Flutter v1 build, closed beta, and Q3 2026 launch.":"Reisontdekking is een van de grootste onopgeloste vlakken in een industrie van vele biljoenen. Elke swipe, bracket en veto traint een eigen voorkeursgraaf die geen concurrent heeft - hetzelfde soort vliegwiel dat Hopper gebruikte om een gerapporteerde waardering van $5 miljard te bereiken, één laag eerder in de reis gebouwd. Kept staat in de App Store. Een derde product is in een vroege ontwikkelfase. De kapitaalronde - € 350.000 op een Post-Money SAFE (cap van US$4,5M) - financiert de bouw van Flutter v1, de closed beta en de lancering in Q3 2026.","Veyago Inc. is a New York C-Corporation building a catalogue of private, intelligent apps for iOS and beyond. Its first app, Kept, is on the App Store. Its flagship, Veyago travel, launches Q3 2026. Press contact: hello@veyago.cloud.":"Veyago Inc. is een New York C-Corporation die een catalogus van private, intelligente apps bouwt voor iOS en daarbuiten. De eerste app, Kept, staat in de App Store. Het vlaggenschip, Veyago travel, lanceert in Q3 2026. Perscontact: hello@veyago.cloud."},"attrs":{"A stylised world map with a travel route":"Een gestileerde wereldkaart met een reisroute","A Veyago destination feature with Save, Bracket, and Book & Plan actions along the bottom of the screen":"Een Veyago-bestemmingsfunctie met de acties Save, Bracket en Book & Plan onderaan het scherm","An aircraft wing above a sea of clouds at golden hour":"Een vliegtuigvleugel boven een zee van wolken tijdens het gouden uur","Cassian Drefke - Founder & CEO, Veyago":"Cassian Drefke - Founder & CEO, Veyago","Close menu":"Menu sluiten","Kept app":"Kept-app","Kept app showing upcoming items sorted by what":"Kept-app met aankomende items gesorteerd op wat","Kept Insights showing warranty value, monthly subscription costs and upcoming renewals":"Kept Insights met garantiewaarde, maandelijkse abonnementskosten en aankomende verlengingen","Kept Library showing receipts, IDs, manuals and renewals neatly organized":"Kept Library met bonnen, ID's, handleidingen en verlengingen netjes geordend","Kept showing upcoming expiry dates and reminders":"Kept met aankomende vervaldatums en herinneringen","Kept Upcoming timeline showing items sorted by what is due soonest":"Kept Upcoming-tijdlijn met items gesorteerd op wat het eerst aan de beurt is","Menu":"Menu","Open menu":"Menu openen","Primary":"Primair","The IE Global home page":"De homepage van IE Global","The Kept app showing upcoming items sorted by what":"De Kept-app met aankomende items gesorteerd op wat","The Tanja Drefke Consult home page":"De homepage van Tanja Drefke Consult","The TDC Digital Advisory home page":"De homepage van TDC Digital Advisory","The Veyago Discover screen - an editorial feature on Tokyo with time-sensitive in-season picks":"Het Veyago Discover-scherm - een redactionele feature over Tokio met seizoensgebonden picks","The Veyago Discover screen - an editorial Veyago Exclusive feature on Tokyo with a Read the piece button and time-sensitive in-season picks":"Het Veyago Discover-scherm - een redactionele Veyago Exclusive-feature over Tokio met een Read the piece-knop en seizoensgebonden picks","The studio pipeline, from research to shipped":"De studiopipeline, van onderzoek tot uitgebracht","The Veyago travel home page":"De homepage van Veyago travel","What holds true of this app":"Wat van deze app waar is","Kept app showing upcoming items sorted by what's next":"De Kept-app met aankomende items, gesorteerd op wat het eerst aan de beurt is"},"html":{"faq.delete":"In Kept verwijder je elk item in de app, of verwijder je de app om de lokale data weg te halen; iCloud-data beheer je in Instellingen → [je naam] → iCloud. Voor Veyago travel kun je je account vanuit de app exporteren of verwijderen. Zie ons <a href=\"/privacy/\">privacybeleid</a>.","faq.launch":"Q3 2026. <a href=\"/veyago/\">Houd me op de hoogte</a> en we mailen je op de dag dat het live is.","faq.bug":"Laat het ons weten - mail <a href=\"mailto:hello@veyago.cloud?subject=Bug%20report\">hello@veyago.cloud</a> met wat er gebeurde, je apparaat en je iOS-versie. Het helpt echt.","faq.policies":"Het <a href=\"/privacy/\">privacybeleid van Veyago travel</a> en het <a href=\"/kept-privacy/\">privacybeleid van Kept</a>."},"meta":{"/":{"title":"Private iOS-apps & websites voor bedrijven | Veyago","description":"Veyago is een onafhankelijke studio: rustige, private iOS-apps - en snelle, vindbare websites voor bedrijven wereldwijd, vanaf $ 699. Geen dark patterns."},"/apps/":{"title":"Onze apps - Kept en Veyago travel | Veyago","description":"De Veyago-appcatalogus - Kept en Veyago travel, beide binnenkort beschikbaar. Private, intelligente apps die van jou zijn, geen software die jou bezit."},"/kept/":{"title":"Kept - Private garantie- en bonnentracker voor iOS | Veyago","description":"Kept houdt alles met een datum bij - garanties, bonnen, documenten, abonnementen - en herinnert je voordat het verloopt. Volledig op je apparaat, geen accounts, geen servers. iOS."},"/veyago/":{"title":"Waar zullen we naartoe gaan? De app om met je groep een reis te kiezen | Veyago","description":"Weet je niet waarheen? Veyago maakt van het ontdekken van bestemmingen een swipe-en-bracket-toernooi - alleen of met je groep - en plant daarna de reis. Vanaf Q3 2026."},"/company/":{"title":"Over Veyago Inc. - studio, oprichter en investeerders | Veyago","description":"Veyago Inc. is een New Yorkse C-Corp die private, intelligente iOS-apps bouwt. Het verhaal van de oprichter, tractie, de Wefunder-ronde en een press kit. Kept komt uit in juni 2026."},"/team/":{"title":"Het team achter Veyago | Veyago","description":"Maak kennis met het kleine, door de oprichter geleide team achter Veyago's private iOS-apps - Kept en Veyago travel - met een hoge lat gebouwd en het waard om op je telefoon te houden."},"/approach/":{"title":"Onze aanpak - privacy eerst, geen dark patterns | Veyago","description":"Hoe Veyago bouwt: privacy als standaard, AI op je apparaat, geen dark patterns, eerlijke prijzen. De principes achter Kept en Veyago travel - en wat we nooit zullen doen."},"/services/":{"title":"Studio voor productdesign en engineering te huur | Veyago","description":"De studio achter Kept en Veyago travel neemt een paar externe iOS-product- en engineeringprojecten per jaar aan - privacy eerst, gebouwd om te blijven. Laten we praten."},"/support/":{"title":"Ondersteuning en hulp voor Veyago-apps | Veyago","description":"Hulp nodig met Kept of Veyago travel? Scannen, herinneringen, iCloud-synchronisatie, aankopen, datavragen - mail hello@veyago.cloud en een echte persoon antwoordt."},"/404":{"title":"Pagina niet gevonden | Veyago","description":""},"/journal/":{"title":"Articles | Veyago","description":"Bouwlogs, onderzoeksnotities en af en toe een mening uit de studio."},"/wallpapers/":{"title":"Wallpapers | Veyago","description":"Gratis te downloaden - gemaakt voor het merk en je startscherm. Niets gevolgd, niets verkocht."},"/projects/":{"title":"Projects - het onderzoek vóór de bouw | Veyago","description":"Binnen de Veyago-studio: het onderzoek dat aan elke app voorafgaat, de pipeline van een vraag naar een uitgebracht product, en de working papers achter Kept en de these over intelligentie op je apparaat."},"/websites/":{"title":"Website laten maken vanaf € 750 - vaste prijs, snel, van jou | Veyago","description":"Websites voor kleine bedrijven tegen een vaste prijs: landingspagina's vanaf € 750, meerdere pagina's, SEO en de dashboards erachter. Met de hand geschreven, snel, van jou."}}});
